import os
import json

session_dir = os.environ.get('RLM_SESSION_DIR')
state_file = os.path.join(session_dir, 'kernel-state.json')

with open(state_file, 'r') as f:
    state_data = json.load(f, strict=False)  # Allow non-strict JSON parsing

def find_text_nodes(obj, path="", limit=5):
    """Recursively find text nodes in state object"""
    found = []
    if not isinstance(obj, dict):
        return found

    for key, val in obj.items():
        current_path = f"{path}.{key}" if path else key
        if 'content' in key.lower() or 'text' in key.lower():
            if isinstance(val, str) and len(val) > 50:
                found.append((current_path, val[:300]))
            elif isinstance(val, dict):
                # Check for type='text' structures
                for k, v in val.items():
                    if v and isinstance(v, str):
                        found.append((f"{current_path}.{k}", v[:300]))
            elif isinstance(val, list):
                for item in val[:3]:
                    if isinstance(item, dict):
                        for k, v in item.items():
                            if v and isinstance(v, str):
                                found.append((f"{current_path}.{k}", v[:300]))
        elif isinstance(val, dict):
            find_text_nodes(val, current_path)
        elif isinstance(val, list):
            for item in val[:2]:
                if isinstance(item, dict):
                    find_text_nodes(item, f"{current_path}[]")

    return found[:limit]

texts = find_text_nodes(state_data)
print("Found text nodes:")
for path, text in texts:
    print(f"\n{path}:")
    if 'cluster' in path.lower() or 'token' in path.lower() or 'row' in path.lower() or 'grid' in path.lower():
        print("=" * 50)
        # Try to extract grid rows
        # The grid should be space-separated numbers
    elif 'demo' in path.lower() or 'pair' in path.lower():
        print("=" * 50)
    print(text)

